<?php
$titulo_pagina='Perfil na VoltX';$estilos_pagina=['/assets/css/profile-card.css?v=1'];require_once __DIR__.'/includes/functions.php';$id=(int)($_GET['id']??0);$stmt=$mysqli->prepare("SELECT id,nome,foto_perfil,tipo,criado_em,ultima_atividade,ultimo_logout FROM usuarios WHERE id=? AND tipo<>'admin'");$stmt->bind_param('i',$id);$stmt->execute();$usuario=$stmt->get_result()->fetch_assoc();if(!$usuario){http_response_code(404);die('Usuário não encontrado.');}$rotulos=['cliente'=>'Cliente','profissional'=>'Profissional','empresa'=>'Empresa'];require_once __DIR__.'/includes/header.php';?>
<div class="container profile-account-page"><section class="identity-card public-user-card"><div class="badge-stripe"></div><div class="badge-top"><span>MEMBRO VOLTX</span><span class="account-chip"><?php echo sanitizar($rotulos[$usuario['tipo']]??'Usuário'); ?></span></div><div class="badge-content"><div class="badge-photo"><?php if($usuario['foto_perfil']): ?><img src="<?php echo sanitizar($usuario['foto_perfil']); ?>" alt="Foto de <?php echo sanitizar($usuario['nome']); ?>"><?php else: ?><span><?php echo sanitizar(mb_strtoupper(mb_substr($usuario['nome'],0,1))); ?></span><?php endif; ?></div><div class="badge-identity"><small>PERFIL PÚBLICO</small><h1><?php echo sanitizar($usuario['nome']); ?></h1><p>Membro desde <?php echo date('m/Y',strtotime($usuario['criado_em'])); ?></p><div class="presence-badge <?php echo usuario_esta_online($usuario)?'online':'offline'; ?>"><i></i><?php echo sanitizar(texto_presenca($usuario)); ?></div></div></div><div class="badge-footer"><span>Dados pessoais e contato permanecem privados.</span></div></section></div><?php require_once __DIR__.'/includes/footer.php'; ?>
